var GRAMMAR_PAGE = String.raw`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Made Well · Grammar of work</title>
<link rel="preload" href="/fonts/ibm-plex-sans-latin.woff2" as="font" type="font/woff2" crossorigin>
<style>${NOTEBOOK_STYLE}
.grammar{max-width:100rem;margin:auto;padding:var(--space-6) var(--space-8)}
.run-picker{display:flex;align-items:end;gap:var(--space-3);margin-bottom:var(--space-6);max-width:68ch}
.run-picker label{display:block;font-size:var(--text-small);margin-bottom:var(--space-1)}.run-picker>div{flex:1;min-width:0}
.overview{margin-bottom:var(--space-6)}.overview h2{font-size:1.5rem;line-height:calc(var(--line)*1.25);margin-bottom:var(--space-2)}
.completion{font-size:var(--text-section);margin:var(--space-3) 0}.completion .answer{font-size:inherit}.completion-count{display:block;font-size:var(--text-small);color:var(--muted)}
.facts{display:flex;flex-wrap:wrap;gap:var(--space-2) var(--space-6);margin:var(--space-3) 0}.facts p{margin:0;font-size:var(--text-small)}
.answer{font:var(--text-small)/var(--line) var(--font-system);margin-left:var(--space-1);white-space:nowrap}.answer.yes{color:var(--accent)}.answer.blocked,.answer.unknown{color:var(--warning)}.answer.no{color:var(--muted)}.answer.running{color:var(--accent)}
.grammar-section{border-top:2px solid var(--line-color);padding-top:var(--space-4);margin-top:var(--space-6)}.grammar-section>h3{margin:0 0 var(--space-3)}
.grammar-step{border:1px solid var(--line-color);border-radius:var(--radius);margin-bottom:var(--space-2);background:var(--paper)}
.grammar-step>summary{display:flex;align-items:baseline;gap:var(--space-2);list-style:none;padding:var(--space-2) var(--space-3)}.grammar-step>summary::-webkit-details-marker{display:none}
.grammar-step>summary:before{content:'+';font-family:var(--font-system);color:var(--muted)}.grammar-step[open]>summary:before{content:'−'}
.grammar-step>summary .answer{margin-left:auto}.function-name{font:var(--text-small)/var(--line) var(--font-system);overflow-wrap:anywhere}
.grammar-step .disclosure-body{padding:var(--space-2) var(--space-3) var(--space-3)}.grammar-step .disclosure-body h4{font-size:var(--text-small);font-weight:500;margin:var(--space-3) 0 var(--space-1)}
.grammar-step .reason{font-size:var(--text-small);color:var(--warning);margin-bottom:var(--space-2)}.grammar-step pre{max-height:20rem;margin:0;font-size:var(--text-code)}
.discovery-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(16rem,1fr);gap:var(--space-4)}.source{min-width:0}.source>summary{padding-top:0}.source pre{max-height:29rem}
.task-list{list-style:none;padding:0;margin:0}.task-list li{display:flex;align-items:baseline;gap:var(--space-3);padding:var(--space-2) 0;border-bottom:1px solid var(--line-color)}
.task-jump{font:inherit;color:var(--accent);background:transparent;border:0;padding:0;text-align:left;cursor:pointer;text-decoration:underline;text-underline-offset:.2em}.task-list .answer{margin-left:auto}
.task-card{border:1px solid var(--line-color);border-radius:var(--radius);padding:var(--space-4);margin-top:var(--space-4);scroll-margin-top:6rem}
.task-card header{display:flex;align-items:baseline;justify-content:space-between;gap:var(--space-3)}.task-card h4{font-size:var(--text-section);font-weight:500;line-height:var(--line);margin:0;overflow-wrap:anywhere}.task-card header .answer{flex-shrink:0}
.task-position{margin:var(--space-1) 0 var(--space-2);font:var(--text-small)/var(--line) var(--font-system);color:var(--muted)}
.phase-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-2);margin-top:var(--space-3);align-items:start}.phase-grid>.grammar-step{margin:0}
.phase-grid>.grammar-step>summary{flex-wrap:wrap}.phase-grid .function-name{white-space:nowrap}
.task-card .notice{margin:var(--space-3) 0}.task-card .notice p{white-space:pre-wrap}.task-evidence{margin-top:var(--space-3)}.task-evidence pre{max-height:24rem}
.read-note{margin-top:var(--space-6);font-size:var(--text-small);color:var(--muted)}.empty{padding:var(--space-6) 0}.empty h2{font-size:1.5rem;line-height:calc(var(--line)*1.25)}
@media(min-width:80rem){.phase-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:48rem){.grammar{padding:var(--space-4)}.app-header{position:static}.run-picker{align-items:stretch;flex-direction:column}.run-picker button{align-self:start}.discovery-layout,.phase-grid{grid-template-columns:1fr}.task-card{padding:var(--space-3);scroll-margin-top:var(--space-3)}.task-card header{align-items:start}.grammar-step>summary{flex-wrap:wrap}.grammar-step>summary .answer{margin-left:auto}.task-list li{flex-wrap:wrap;gap:0 var(--space-2)}.task-list .answer{margin-left:0}.source{margin-top:var(--space-2)}}
</style></head><body>
<a class="skip" href="#work">Skip to grammar</a>
<header class="app-header"><h1>Made Well</h1><a href="/">Work</a><a href="/grammar" aria-current="page">Grammar</a><a href="/qa">Manual QA</a><span id="connection" role="status">Connecting to the work record…</span></header>
<main class="grammar" id="work" tabindex="-1">
<div class="run-picker"><div><label for="run">Discovery run</label><select id="run" aria-describedby="read-note"><option value="">Loading recorded runs…</option></select></div><button class="action" id="refresh" type="button">Refresh record</button></div>
<div id="empty" class="empty" hidden><h2 id="empty-title"></h2><p id="empty-text"></p></div>
<div id="record" hidden>
<section class="overview" aria-labelledby="work-title"><h2 id="work-title"></h2><p id="work-position" class="system"></p><p class="completion">Discovery complete?<strong class="answer" id="discovery-complete"></strong><span class="completion-count" id="discovery-count"></span></p><div class="facts"><p>Task list produced?<strong class="answer" id="task-list-produced"></strong></p><p>Every task delivered?<strong class="answer" id="all-delivered"></strong></p><p>Runner active?<strong class="answer" id="runner-active"></strong></p></div><p class="system" id="last-activity"></p><div id="discovery-organs"></div></section>
<section class="grammar-section" aria-labelledby="capture-heading"><h3 id="capture-heading">Step 1): Capture Raw Input</h3><div class="discovery-layout"><div id="discovery-steps"></div><details class="source" id="raw-source"><summary>Raw input · exact recorded text</summary><pre id="raw-text" tabindex="0"></pre></details></div></section>
<section class="grammar-section" aria-labelledby="tasks-heading"><h3 id="tasks-heading">Step 2) generate task list</h3><p id="task-list-status"></p><ul class="task-list" id="task-list"></ul></section>
<section class="grammar-section" aria-labelledby="delivery-heading"><h3 id="delivery-heading">Step 3) complete the fucking task list</h3><p id="parallel-status" class="muted"></p><div id="delivery-tasks"></div></section>
</div>
<p class="read-note" id="read-note">Read-only view of the same durable work record. Every completion checkmark requires current accepted evidence. Missing records are not complete. Recorded assertions and automated acceptance have distinct provenance.</p>
</main>
<script>
${EVIDENCE_SCRIPT}
const $=id=>document.getElementById(id),runSelect=$('run'),connection=$('connection');
let selected=Number(new URL(location.href).searchParams.get('id'))||null,loading=false,runKey='',lastGood=null;
const stepNodes=new Map(),taskNodes=new Map(),listNodes=new Map();
const stateNames={yes:'YES · complete',no:'NO · pending',unknown:'NO · not recorded',running:'NO · running',blocked:'NO · blocked'};
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
function setText(n,value){const text=value===null||value===undefined?'':String(value);if(n.textContent!==text)n.textContent=text}
function answer(n,state,text){n.className='answer '+state;setText(n,(state==='yes'?'✓ ':'○ ')+(text||stateNames[state]||'NO · unknown'))}
function dataText(value){return value===null||value===undefined?'Not recorded':typeof value==='string'?value:JSON.stringify(value,null,2)}
function empty(title,text){$('empty').hidden=false;$('record').hidden=true;setText($('empty-title'),title);setText($('empty-text'),text)}
function phaseNode(parent,key){let r=stepNodes.get(key);if(r)return r;const root=node('details','grammar-step'),summary=node('summary'),name=node('span','function-name'),state=node('span','answer'),body=node('div','disclosure-body'),reason=node('p','reason'),input=node('pre'),output=node('pre'),evidence=node('pre');root.dataset.step=key;input.tabIndex=output.tabIndex=evidence.tabIndex=0;summary.append(name,state);body.append(reason,node('h4',null,'Recorded invocation input'),input,node('h4',null,'Accepted result'),output,node('h4',null,'Recorded evidence'),evidence);root.append(summary,body);parent.append(root);r={root,name,state,reason,input,output,evidence};stepNodes.set(key,r);return r}
function updatePhase(parent,key,s){const r=phaseNode(parent,key);setText(r.name,s.label);answer(r.state,s.state);setText(r.reason,s.reason);r.reason.hidden=!s.reason;setText(r.input,dataText(s.input));setText(r.output,dataText(s.evidence?.acceptedOutput??s.output));let unavailable=r.root.querySelector('[data-invocation-unavailable]');const provenance=s.evidence?.provenance;const missing=provenance&&(provenance.state?provenance.state!=='linked':Object.values(provenance).some(p=>p?.state!=='linked'));if(missing){if(!unavailable){unavailable=node('p','system','Invocation not recorded');unavailable.dataset.invocationUnavailable='';r.input.before(unavailable)}}else unavailable?.remove();const later=s.evidence?.laterAttempts;for(const attempts of later?(later.entries?[later]:Object.values(later)):[])for(const attempt of attempts?.entries??[])exactEvidence(r.root.lastElementChild,'later:'+key+':'+attempt.event,'Later attempt · '+attempt.outcome+' · '+attempt.at,attempt.evidence);setText(r.evidence,dataText({...s.evidence,retainedOutput:s.output,metrics:s.metrics}));return r.root}
function clearSelection(){stepNodes.clear();taskNodes.clear();listNodes.clear();$('discovery-steps').replaceChildren();$('delivery-tasks').replaceChildren();$('task-list').replaceChildren();$('raw-source').open=false;for(const n of document.querySelectorAll('[data-current-work],[data-work-organs]'))n.remove()}
function select(id){if(id===selected)return;selected=id;lastGood=null;clearSelection();const url=new URL(location.href);if(id)url.searchParams.set('id',String(id));else url.searchParams.delete('id');history.replaceState(null,'',url);void refresh()}
function taskNode(t){let r=taskNodes.get(t.id);if(r)return r;const root=node('section','task-card'),header=node('header'),title=node('h4'),done=node('strong','answer'),position=node('p','task-position'),readiness=node('p','task-readiness'),facts=node('div','facts'),entered=node('strong','answer'),tests=node('strong','answer'),verified=node('strong','answer'),blocker=node('div','notice'),blockTitle=node('h3',null,'What prevents completion?'),blockText=node('p'),grid=node('div','phase-grid'),details=node('details','task-evidence'),proof=node('pre');root.id='task-'+t.id;root.tabIndex=-1;title.id='task-title-'+t.id;root.setAttribute('aria-labelledby',title.id);header.append(title,done);for(const [label,value]of [['Entered delivery?',entered],['Acceptance defined?',tests],['Automated acceptance passed?',verified]]){const p=node('p',null,label);p.append(value);facts.append(p)}blocker.append(blockTitle,blockText);proof.tabIndex=0;details.append(node('summary',null,'Inspect completion and acceptance evidence'),proof);root.append(header,position,readiness,facts,blocker,grid,details);$('delivery-tasks').append(root);r={root,title,done,position,readiness,entered,tests,verified,blocker,blockText,grid,proof};taskNodes.set(t.id,r);return r}
function updateTask(t){const r=taskNode(t);setText(r.title,'#'+t.id+' · '+t.title);answer(r.done,t.delivered?'yes':'no',t.delivered?'DELIVERED':'NOT DELIVERED');setText(r.position,t.objective+' · Owner: '+t.owner+' · Next: '+t.nextAction+' · Current phase: '+(t.currentPhase||'not entered')+' · '+t.status+(t.currentJob?' · '+t.currentJob:''));setText(r.readiness,['shipped','completed'].includes(t.status)&&!t.delivered?'Recorded as '+(t.status==='shipped'?'delivered':'completed')+'; current evidence incomplete. '+t.readiness.reason:t.readiness.reason);const organs=workOrgans(r.root,t.organs,t.id,t.organJobs,t.currentJob);if(organs.nextElementSibling!==r.grid)r.root.insertBefore(organs,r.grid);const handoff=currentWork(r.root,t.currentHandoff,t.id);if(handoff.nextElementSibling!==organs)r.root.insertBefore(handoff,organs);answer(r.entered,t.enteredDelivery?'yes':'no');answer(r.tests,t.testsCreated?'yes':'no',t.testsCreated?'YES · '+t.testCount+' checks':'NO');answer(r.verified,t.verification.passed===true?'yes':t.verification.passed===false?'blocked':'no',t.verification.passed===true?'YES':t.verification.passed===false?'NO · failed':'NO · not recorded');r.blocker.hidden=!t.blocker;setText(r.blockText,t.blocker?t.blocker.message:'');for(const p of t.phases)updatePhase(r.grid,'task:'+t.id+':'+p.job,p);setText(r.proof,dataText({completion:t.completion,blockers:t.blockers,verification:t.verification,shipment:t.shipment,readiness:t.readiness,dependsOn:t.after,lastTaskUpdate:t.updated}));let li=listNodes.get(t.id);if(!li){li=node('li');const b=node('button','task-jump'),a=node('strong','answer');b.type='button';b.addEventListener('click',()=>{r.root.focus({preventScroll:true});r.root.scrollIntoView({block:'start'})});li.append(b,a);$('task-list').append(li);listNodes.set(t.id,li)}setText(li.firstElementChild,'#'+t.id+' · '+t.title);answer(li.lastElementChild,t.delivered?'yes':t.blocker?'blocked':'no',t.delivered?'DELIVERED':t.blocker?'HELD':t.enteredDelivery?'IN DELIVERY':'NOT STARTED')}
function render(view){$('empty').hidden=true;$('record').hidden=false;setText($('work-title'),view.discovery.title);setText($('work-position'),'Discovery #'+view.discovery.id+' · '+view.discovery.status+(view.discovery.currentJob?' · '+view.discovery.currentJob:''));setText($('raw-text'),view.discovery.source);answer($('discovery-complete'),view.discovery.complete?'yes':'no',view.discovery.complete?'YES · complete':'NO · pending');setText($('discovery-count'),view.discovery.completedStepCount+' of '+view.discovery.requiredStepCount+' required functions complete.');answer($('task-list-produced'),view.discovery.taskListProduced?'yes':'no');answer($('all-delivered'),view.allDelivered?'yes':'no',view.allDelivered?'YES':view.tasks.length?'NO':'NO · no delivered tasks');answer($('runner-active'),view.runner.active?'yes':'no',view.runner.active?'YES':'NO · stopped');setText($('last-activity'),'Last recorded activity: '+(view.lastEventAt||'not recorded'));workOrgans($('discovery-organs'),view.discovery.organs,view.discovery.id,view.discovery.organJobs,view.discovery.currentJob);currentWork($('discovery-steps').parentElement,view.discovery.currentHandoff,view.discovery.id);for(const s of view.discovery.steps)updatePhase($('discovery-steps'),'discovery:'+s.job,s);setText($('task-list-status'),view.discovery.taskListProduced?view.tasks.length+' generated task'+(view.tasks.length===1?'':'s')+'.':'Task list has not been produced.');setText($('parallel-status'),view.parallel.observed?'Overlapping task execution is recorded for '+view.parallel.pairs.map(p=>p.map(id=>'#'+id).join(' and ')).join('; ')+'.':'No overlapping task execution is established by the current record.');for(const t of view.tasks)updateTask(t);const ids=new Set(view.tasks.map(t=>t.id));for(const [id,r]of taskNodes)if(!ids.has(id)){r.root.remove();taskNodes.delete(id);listNodes.get(id)?.remove();listNodes.delete(id);for(const [k,s]of stepNodes)if(k.startsWith('task:'+id+':')){s.root.remove();stepNodes.delete(k)}}lastGood=view;setText(connection,'Connected · record read '+view.observedAt);connection.className=''}
async function json(url){const response=await fetch(url,{cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok){let detail='';try{const body=await response.json();detail=body.message||body.error||''}catch{}throw new Error('HTTP '+response.status+(detail?' · '+detail:''))}return response.json()}
async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;try{const runs=await json('/api/grammar');const options=runs.items||[];const key=JSON.stringify(options);if(key!==runKey){const focused=document.activeElement===runSelect;const value=String(selected||'');runSelect.replaceChildren();if(!options.length){const o=node('option',null,'No discovery runs recorded');o.value='';runSelect.append(o)}for(const x of options){const o=node('option',null,'#'+x.id+' · '+x.title+' · '+x.status);o.value=String(x.id);runSelect.append(o)}runKey=key;runSelect.value=value;if(focused)runSelect.focus({preventScroll:true})}runSelect.disabled=!options.length;if(!selected&&options.length){selected=options[options.length-1].id;runSelect.value=String(selected);const url=new URL(location.href);url.searchParams.set('id',String(selected));history.replaceState(null,'',url)}if(!selected){empty('No discovery work recorded.','Start a discovery run in this Made Well store to see its prescribed functions, outputs and generated tasks.');setText(connection,'Connected · no discovery runs');connection.className='';return}const requested=selected;const view=await json('/api/grammar/'+requested);if(selected!==requested)return;if(!view||!view.discovery)throw new Error('The selected work record has no discovery context.');if(view.discovery.id!==selected){selected=view.discovery.id;runSelect.value=String(selected);const url=new URL(location.href);url.searchParams.set('id',String(selected));history.replaceState(null,'',url)}render(view)}catch(error){connection.className='error';setText(connection,'Record unavailable · '+error.message+(lastGood?' · showing the last successful read':'') );if(!lastGood)empty('The work record is unavailable.','Refresh the record or choose another discovery run. No completion state is inferred from this connection failure.')}finally{loading=false;$('refresh').disabled=false}}
runSelect.addEventListener('change',()=>select(Number(runSelect.value)||null));$('refresh').addEventListener('click',refresh);void refresh();setInterval(refresh,2000);
</script></body></html>`;

