function functionProgress(item, store) {
  const flow = item.flow ?? { loop: "delivery", accepted: [] };
  const steps = laneOf(item.pack)[flow.loop];
  const step = steps.find((s) => !flow.accepted.includes(s.job));
  const job = step?.job ?? null;
  const contract = step?.args?.contract && typeof step.args.contract === "object" ? step.args.contract : {};
  const label3 = typeof contract.label === "string" ? contract.label : step ? `${step.job}()` : "Finish the saved flow";
  const required3 = step ? [typeof contract.purpose === "string" ? contract.purpose : step.duty || "Return an output that satisfies this function\u2019s saved contract.", ...step.check ? ["The configured acceptance check must pass before this output is accepted."] : []] : ["Every configured function must have its accepted output saved."];
  const result3 = (allowed, kind, reason, problem = null) => ({
    gate: "saved-function-contract",
    allowed,
    kind,
    job,
    label: label3,
    reason,
    required: required3,
    problem
  });
  const invalid4 = flow.accepted.findIndex((accepted) => {
    const saved = steps.find((s) => s.job === accepted);
    return !saved || typeof (saved.track === "main" ? item.outputs[accepted] : item.flow?.tracks?.[saved.track ?? ""]?.outputs[accepted]) !== "string";
  });
  if (invalid4 >= 0) return result3(false, "repair", `Saved acceptance at position ${invalid4 + 1} does not match the configured function and its output.`, `Invalid accepted function prefix at position ${invalid4 + 1}.`);
  if (item.status === "candidate") return result3(false, "select", "This proposed task must be selected before delivery can start.");
  if (item.status === "held") return result3(false, "resume", item.hold?.message ?? "Resolve the recorded block before retrying this work.");
  if (item.status === "paused") return result3(false, "resume", item.hold?.message ?? "Continue this saved checkpoint before work can resume.");
  if (["completed", "shipped", "discovered", "dropped"].includes(item.status)) return result3(false, "done", item.status === "dropped" ? "This work was stopped." : "This configured flow has ended. Its result evidence remains separately inspectable.");
  const pending = (item.after ?? []).filter((id2) => !["completed"].includes(store.get(id2)?.status ?? ""));
  if (pending.length) return result3(false, "wait", `Waiting for prerequisite work: ${pending.map((id2) => `#${id2}`).join(", ")}.`);
  const eligibility = readiness(store, item);
  if (!eligibility.ready) return result3(false, "wait", eligibility.reasons.join("; "));
  return result3(true, step ? "run" : "finish", item.rejected ? `Correct this function\u2019s refused return: ${item.rejected}` : step ? "Earlier configured functions have their outputs saved; this function can proceed." : "All configured outputs are saved; the flow can be finalized.");
}

